CREATE OR REPLACE PROCEDURE public.sp_update_child_consent_document(IN p_id uuid, IN p_tenant_id uuid, IN p_status character varying, IN p_admin_reviewed_by uuid, IN p_admin_reviewed_at timestamp with time zone, IN p_admin_review_notes text, IN p_approved_at timestamp with time zone, IN p_sent_at timestamp with time zone, IN p_signed_at timestamp with time zone, IN p_declined_at timestamp with time zone, IN p_withdrawn_at timestamp with time zone, IN p_signed_document_storage_key character varying, IN p_signed_document_checksum character varying)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE child_consent_documents     SET status = p_status,         admin_reviewed_by = p_admin_reviewed_by,         admin_reviewed_at = p_admin_reviewed_at,         admin_review_notes = p_admin_review_notes,         approved_at = p_approved_at,         sent_at = p_sent_at,         signed_at = p_signed_at,         declined_at = p_declined_at,         withdrawn_at = p_withdrawn_at,         signed_document_storage_key = p_signed_document_storage_key,         signed_document_checksum = p_signed_document_checksum,         row_version = row_version + 1     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
